function maxSizedArray(s) {
  function orSum(n) {
    let total = 0;
    for (let bit = 1; bit < n; bit *= 2) {
      const block = 2 * bit;
      const ones = Math.floor(n / block) * bit + Math.max(0, (n % block) - bit);
      const zeros = n - ones;
      total += bit * (n * n - zeros * zeros);
    }
    return total;
  }

  let low = 1;
  let high = 1200;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    const arraySum = (mid * (mid - 1) / 2) * orSum(mid);
    if (arraySum <= s) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

