function maxSizedArray(s) {
  // Grow n one step at a time, keeping exact running sums built with direct OR operations.
  let n = 1;
  let indexSum = 0; // 0 + 1 + ... + (n - 1)
  let pairSum = 0; // (j | k) summed over all j, k below n
  for (;;) {
    let added = n; // the new pair (n, n)
    for (let j = 0; j < n; j++) added += 2 * (j | n); // the new pairs (j, n) and (n, j)
    if ((indexSum + n) * (pairSum + added) > s) return n;
    indexSum += n;
    pairSum += added;
    n++;
  }
}

