function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // The array total for n, straight from the definition with a double loop over (j, k).
  const total = n => {
    let or = 0;
    for (let j = 0; j < n; j++) for (let k = 0; k < n; k++) or += j | k;
    return n * (n - 1) / 2 * or;
  };
  const style = pick(3);
  if (size === 'large') {
    if (style === 0) return [1000000000000000];
    if (style === 1) return [total(1000 + pick(197)) + pick(3) - 1];
    return [Math.floor(rand() * 1e15)];
  }
  // Small cases: tiny values, values right at a boundary total (minus 1, equal, plus 1), and values of every magnitude.
  if (style === 0) return [pick(60)];
  if (style === 1) return [Math.max(0, total(1 + pick(40)) + pick(3) - 1)];
  return [Math.floor(10 ** (rand() * 12))];
}
